import{_ as a,o as n,c as r,j as e,a as o}from"./chunks/framework.DdpBa4_E.js";const h=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"books/attached/103-争吵令我们更幸福？.md","filePath":"books/attached/103-争吵令我们更幸福？.md","lastUpdated":1794298621000}'),l={name:"books/attached/103-争吵令我们更幸福？.md"};function s(d,t,c,p,_,i){return n(),r("div",null,[...t[0]||(t[0]=[e("h3",{id:"争吵令我们更幸福",tabindex:"-1"},[o("争吵令我们更幸福？ "),e("a",{class:"header-anchor",href:"#争吵令我们更幸福","aria-label":'Permalink to "争吵令我们更幸福？"'},"​")],-1),e("p",null,"在恋爱关系中有一个很普遍的关于冲突的误区，那就是很少吵嘴的亲密关系才是高质量的。这种观点认为，如果你和你的伴侣十分合拍，就往往会在很多问题上达成共识，极少发生分歧。甚至有时候，冲突被看作是两人不合拍，或者亲密关系土崩瓦解的“试金石”。但依恋关系理论告诉我们，这类猜想是不那么站得住脚的，所有的伴侣，即使是安全型伴侣，也会有争吵的时候。事实上，区别亲密关系是否达到满意度水平的指标，并不是两人会产生多少争执，而是两人争执的方式和缘由。依恋关系的研究者们发现，有时候冲突也是一种契机，可以令伴侣彼此更加靠近对方，令关系更加紧密。",-1),e("p",null,"冲突主要分为两种，基本生计型（the bread-and-butter type）与亲密导向型（the intimacy-centered type）。在第8章里，我们就见证了那些亲密需求截然相反的伴侣，硬要一同相处所产生的后果，即使他们有着善意的出发点，非常努力想要达成共识。同时我们也见证了，这些相互冲突的需要，是如何蔓延到生活的方方面面的，而且往往是其中一方一味做出让步。基本生计型的冲突，往往是不涉及有关亲密感的困扰的。",-1),e("p",null,"||基本生计型冲突",-1),e("p",null,"正如其名称那样，基本生计型冲突就是日常生活中，由于双方的志趣与性格差异而产生的不可避免的争执——比如看什么电视频道；空调设定到多少度；点中餐还是印度菜等等。这类的分歧事实上颇有益处，因为它们有助于促进你学会与另一个人生活，也学着互相妥协。人类社会中最为残酷的刑罚之一就是单独拘禁，我们是社会动物，生命因为与他人的关系而更加美好。虽然说有时候稍微调整自己的思维与行为，对我们来说意味着跳出舒适圈，但这也能令我们的思维保持青春活力，甚至有助于大脑细胞的再生。",-1),e("p",null,"然而，学会处处为他人着想，即使是他人的需要和喜好与自己相反，也要顾及，这显然说起来容易做起来难。有趣的是，安全型人群天生就有这种能力。他们善于在争吵的时候将战火冷却，将白热化的冲突化解开来。若是你冷不丁发现，居然有人真心实意地在争执之中，站在你的角度思考问题，考虑到你的志趣，那你大概是遇到了安全型依恋风格的人。那么对于并不具备这类技能的人，这是不是一种很有益的自然素质呢？",-1),e("p",null,"事实上，经过仔细观察，我们可以透过安全型人群的这种本能行为，发现背后有一些规律。这些规律不但关乎所谓的魔法能力，更加关乎他们有益的实践。我们不仅要学会辨认出安全型依恋人群用于减弱、化解冲突的五类特殊行为，还应该坚信这些行为是可以通过学习获得的。成人依恋理论显示，依恋风格的形成需要很长的时间以及不断地在调整，因此我们是很有可塑性的。学习新的亲密关系技能，什么时候都不会迟。",-1)])])}const m=a(l,[["render",s]]);export{h as __pageData,m as default};
